def compute(vars):
    beginning = vars["v1"]
    ending = vars["v2"]

    if beginning == 0:
        return None

    percentage_increase = (ending - beginning) / beginning * 100

    return {
        "value": percentage_increase,
        "trace": {
            "beginning": beginning,
            "ending": ending,
            "change": ending - beginning,
            "percentage_increase": percentage_increase,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
